// src/design-system/components/data-display/contexts/data-list-table.context.ts

import type {
  DataViewTableSortConfig,
  FormattedListItem,
  FormattedTableHeader,
  FormattedTableColumn,
} from "@/design-system/components/data-display/types/data-view-table.type";
import type {
  DataViewBatchActionsGenerator,
  DataViewItemActionsGenerator,
} from "@/design-system/components/data-display/types/data-view.type";
import type { RefObject } from "react";
import { createContext, useContext } from "react";

export type DataViewTableContextValue = {
  headers: FormattedTableHeader[];
  items: FormattedListItem[];
  page?: number;
  pageSize?: number;
  initialSortColumnIndex?: number;
  initialSortOrder?: "asc" | "desc";
  batchActions?: DataViewBatchActionsGenerator[];
  itemActions?: DataViewItemActionsGenerator[];
  withNumbering?: boolean;
  virtualized?: boolean;
  fixedItemHeight?: boolean;
  tableContainerRef: RefObject<HTMLDivElement | null>;
  tableContainerEl: HTMLDivElement | null;

  sortConfig: DataViewTableSortConfig;
  toggleSort: (columnIndex: number) => void;
  sortedItems: FormattedListItem[];
  selectedItemIds: string[];
  selectedItems: FormattedListItem[];
  isAllItemsSelected: boolean;
  toggleItemSelection: (item: FormattedListItem) => void;
  selectAllItems: (isChecked: boolean) => void;
  clearSelectedItems: () => void;
  canBatchSelect: boolean;
  renderTdCell?: (
    column: FormattedTableColumn,
    item: FormattedListItem,
    columnIndex: number,
  ) => React.ReactNode;
};

export const DataViewTableContext =
  createContext<DataViewTableContextValue | null>(null);

export const useDataViewTableContext = () => {
  const ctx = useContext(DataViewTableContext);
  if (!ctx) {
    throw new Error(
      "DataView.Table compound components must be used within <DataView.Table.Root>",
    );
  }
  return ctx;
};

// src/design-system/components/data-display/ui/clipboard-button.tsx

import type { ButtonProps } from "@/design-system/components/button/types/button.type";
import {
  Button,
  IconButton,
} from "@/design-system/components/button/ui/button";
import { Clipboard } from "@/design-system/components/data-display/ui/clipboard";

export type ClipboardButtonProps = ButtonProps & {
  value?: string;
  isIconButton?: boolean;
};

export const ClipboardButton = (props: ClipboardButtonProps) => {
  // Props
  const { value, isIconButton = true, ...restProps } = props;

  return (
    <>
      {isIconButton && (
        <Clipboard.Root value={value}>
          <Clipboard.Trigger asChild>
            <IconButton {...restProps}>
              <Clipboard.Indicator />
            </IconButton>
          </Clipboard.Trigger>
        </Clipboard.Root>
      )}

      {!isIconButton && (
        <Clipboard.Root value={value}>
          <Clipboard.Trigger asChild>
            <Button {...restProps}>
              <Clipboard.Indicator />
              <Clipboard.CopyText />
            </Button>
          </Clipboard.Trigger>
        </Clipboard.Root>
      )}
    </>
  );
};

// src/design-system/components/data-display/utils/countdown.utils.ts

export type CountdownParts = {
  days: number;
  hours: number;
  minutes: number;
  seconds: number;
  isFinished: boolean;
};

const SECOND_IN_MS = 1000;
const MINUTE_IN_SECONDS = 60;
const HOUR_IN_SECONDS = 60 * MINUTE_IN_SECONDS;
const DAY_IN_SECONDS = 24 * HOUR_IN_SECONDS;

export const getCountdownParts = (
  finishedAt: string | Date,
  now: Date = new Date(),
): CountdownParts => {
  const finishedAtDate =
    finishedAt instanceof Date ? finishedAt : new Date(finishedAt);
  const difference = finishedAtDate.getTime() - now.getTime();

  if (Number.isNaN(difference) || difference <= 0) {
    return {
      days: 0,
      hours: 0,
      minutes: 0,
      seconds: 0,
      isFinished: true,
    };
  }

  const totalSeconds = Math.floor(difference / SECOND_IN_MS);

  return {
    days: Math.floor(totalSeconds / DAY_IN_SECONDS),
    hours: Math.floor((totalSeconds % DAY_IN_SECONDS) / HOUR_IN_SECONDS),
    minutes: Math.floor(
      (totalSeconds % HOUR_IN_SECONDS) / MINUTE_IN_SECONDS,
    ),
    seconds: totalSeconds % MINUTE_IN_SECONDS,
    isFinished: false,
  };
};

const DEFAULT_COUNTDOWN_FORMAT = "{DD}:{HH}:{mm}:{ss}";

export const formatCountdownParts = (
  parts: CountdownParts,
  format = DEFAULT_COUNTDOWN_FORMAT,
): string => {
  if (parts.isFinished) return "Kedaluwarsa";

  const replacements: Record<string, string> = {
    "{days}": String(parts.days),
    "{hours}": String(parts.hours),
    "{minutes}": String(parts.minutes),
    "{seconds}": String(parts.seconds),
    "{DD}": String(parts.days).padStart(2, "0"),
    "{HH}": String(parts.hours).padStart(2, "0"),
    "{mm}": String(parts.minutes).padStart(2, "0"),
    "{ss}": String(parts.seconds).padStart(2, "0"),
  };

  return Object.entries(replacements).reduce(
    (output, [token, value]) => output.replaceAll(token, value),
    format,
  );
};

