  wmsVisible: true,
  setWmsVisible: (wmsVisible) => set({ wmsVisible }),
  enabledLayerIds: {},
  layerOpacities: {},
  customLayerConfigs: {},
  toggleLayerId: (layerId) =>
    set((state) => ({
      enabledLayerIds: {
        ...state.enabledLayerIds,
        [layerId]: !state.enabledLayerIds[layerId],
      },
    })),
  setLayerEnabled: (layerId, enabled) =>
    set((state) => ({
      enabledLayerIds: {
        ...state.enabledLayerIds,
        [layerId]: enabled,
      },
