import { CloseButton } from "@/design-system/components/button/ui/close-button";
import { AppIcon } from "@/design-system/components/icon/ui/app-icon";
import {
  DIALOG_OFFSET_X_VAR,
  DIALOG_OFFSET_Y_VAR,
  getDialogOffset,
  updateClickOrigin,
  updateDialogOffset,
} from "@/design-system/components/overlay/stores/dialog-animation-store";
import type {
  DialogCloseButtonProps,
  DialogContentProps,
  DialogRootProps,
} from "@/design-system/components/overlay/types/dialog.type";
import {
  registerFullscreenAnimator,
  triggerFullscreenAnimation,
  unregisterFullscreenAnimator,
} from "@/design-system/components/overlay/utils/fullscreen-animation-registry";
import { Portal } from "@/design-system/components/utilities/ui/portal";
import { useThemeStore } from "@/design-system/stores/theme-store";
import { useFirstMountEffect } from "@/shared/hooks/use-first-mount-effect";
import { back } from "@/shared/utils/client/navigation";
import { Dialog as ChakraDialog } from "@chakra-ui/react";
import { IconSquare, IconSquares } from "@tabler/icons-react";
import {
  createContext,
  useContext,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type Dispatch,
  type MouseEvent,
  type SetStateAction,
} from "react";

export type DialogContextValue = {
  modalKey: string;
  opened: boolean;
  open?: () => void;
  close?: () => void;
  fullscreen: boolean;
  setFullscreen: Dispatch<SetStateAction<boolean>>;
  clickOriginAnimation: boolean;
  size: ChakraDialog.RootProps["size"];
  closeOnInteractOutside?: boolean;
};

export const DialogContext = createContext<DialogContextValue | null>(null);

export function useDialogContext() {
  const context = useContext(DialogContext);

  if (!context) {
    throw new Error("useDialogContext must be used within Dialog.Root");
  }

  return context;
}

// ---------------------------------------------------------------------------

const DialogRoot = (props: DialogRootProps) => {
  // Props
  const {
    modalKey = "dialog",
    opened = false,
    open,
    close,
    clickOriginAnimation = true,
    size = "xs",
    closeOnInteractOutside = true,
    ...restProps
  } = props;

  // Derived Values
  const nestingLevel = modalKey.split(".").length;
  const isNested = nestingLevel > 1;
  const delayMs = nestingLevel;

  // States
  const [delayedOpened, setDelayedOpened] = useState(() =>
    isNested && opened ? false : opened,
  );
  const [fullscreen, setFullscreen] = useState<boolean>(false);

  useFirstMountEffect(
    {
      onFirstMount: () => {
        if (!isNested || !opened) return;

        const timeoutId = setTimeout(() => {
          setDelayedOpened(true);
        }, delayMs);

        return () => clearTimeout(timeoutId);
      },
      onUpdate: () => {
        setDelayedOpened(opened);
        if (!opened) {
          setTimeout(() => {
            setFullscreen(false);
          }, 200);
        }
      },
    },
    [opened, isNested, delayMs],
  );

  const contextValue = useMemo<DialogContextValue>(
    () => ({
      modalKey,
      opened,
      open,
      close,
      clickOriginAnimation,
      fullscreen,
      setFullscreen,
      size,
      closeOnInteractOutside,
    }),
    [
      modalKey,
      opened,
      open,
      close,
      clickOriginAnimation,
      fullscreen,
      setFullscreen,
      size,
      closeOnInteractOutside,
    ],
  );

  return (
    <DialogContext.Provider value={contextValue}>
      <ChakraDialog.Root
        open={delayedOpened}
        lazyMount
        unmountOnExit
        size={fullscreen ? "full" : size}
        scrollBehavior={"outside"}
        {...restProps}
        placement={"center"}
        trapFocus={false}
        preventScroll
        onEscapeKeyDown={() => {
          if (close) {
            close();
          } else {
            back();
          }
          setTimeout(() => setFullscreen(false), 200);
        }}
      />
    </DialogContext.Provider>
  );
};

const DialogTrigger = (props: ChakraDialog.TriggerProps) => {
  // Props
  const { onClick, ...restProps } = props;

  // Contexts
  const { modalKey, open, clickOriginAnimation } = useDialogContext();

  // Handlers
  const initOriginPoint = clickOriginAnimation
    ? (e: MouseEvent) => {
        updateClickOrigin(modalKey, e.currentTarget);
      }
    : undefined;

  return (
    <ChakraDialog.Trigger
      asChild
      onPointerDown={initOriginPoint}
      onClick={(event) => {
        open?.();
        onClick?.(event);
      }}
      {...restProps}
    />
  );
};

const DialogPositioner = (props: ChakraDialog.PositionerProps) => {
  return <ChakraDialog.Positioner {...props} />;
};

const DialogBackdrop = (props: ChakraDialog.BackdropProps) => {
  // Props
  const { onClick, ...restProps } = props;

  // Contexts
  const { close, setFullscreen, closeOnInteractOutside } = useDialogContext();

  return (
    <ChakraDialog.Backdrop
      pointerEvents={"auto"}
      onClick={(event) => {
        if (!closeOnInteractOutside) return;
        if (close) {
          close();
        } else {
          back();
        }
        setTimeout(() => setFullscreen(false), 200);
        onClick?.(event);
      }}
      {...restProps}
    />
  );
};

const DialogContent = (props: DialogContentProps) => {
  // Props
  const { portalled = true, portalRef, backdrop = true, ...restProps } = props;

  // Stores
  const { theme } = useThemeStore();

  // Contexts
  const { modalKey, fullscreen, size, clickOriginAnimation } =
    useDialogContext();

  // Refs
  const contentRef = useRef<HTMLDivElement>(null);

  const isFullscreen = fullscreen || size === "full";
  const zIndex = 1400 + modalKey.split(".").length;

  // Pre-calculate dialog offset synchronously before browser paint
  updateDialogOffset(modalKey);
  const { x, y } = getDialogOffset(modalKey);

  useLayoutEffect(() => {
    let currentAnimation: Animation | null = null;

    registerFullscreenAnimator(modalKey, (next) => {
      const el = contentRef.current;
      if (!el) return;

      currentAnimation = el.animate(
        next
          ? [
              {
                transform: "scale(0.96)",
              },
              {
                transform: "scale(1)",
              },
            ]
          : [
              {
                transform: "scale(1.04)",
              },
              {
                transform: "scale(1)",
              },
            ],
        {
          duration: 300,
          easing: "cubic-bezier(0.22, 1, 0.36, 1)",
          fill: "both",
        },
      );

      currentAnimation.onfinish = () => {
        currentAnimation?.cancel();
        currentAnimation = null;
      };
    });

    return () => {
      currentAnimation?.cancel();
      unregisterFullscreenAnimator(modalKey);
    };
  }, [modalKey]);

  return (
    <Portal disabled={!portalled} container={portalRef}>
      <DialogPositioner zIndex={zIndex} p={isFullscreen ? 0 : 4}>
        {backdrop && <DialogBackdrop />}

        <ChakraDialog.Content
          ref={contentRef}
          overflow={"clip"}
          pos={"relative"}
          bg={"bg.body"}
          rounded={isFullscreen ? 0 : theme.radii.container}
          shadow={"md"}
          style={
            {
              [DIALOG_OFFSET_X_VAR]: `${x}px`,
              [DIALOG_OFFSET_Y_VAR]: `${y}px`,
              ...restProps.style,
            } as CSSProperties
          }
          _open={{
            animation: clickOriginAnimation
              ? "scale-up-overshoot-from-click-origin"
              : "scale-up-overshoot",
            animationDuration: "slowest",
          }}
          _closed={{
            animation: clickOriginAnimation
              ? "scale-down-to-click-origin"
              : "scale-down",
            animationDuration: clickOriginAnimation ? "slow" : "moderate",
          }}
          {...restProps}
        />
      </DialogPositioner>
    </Portal>
  );
};

const DialogCloseTrigger = (props: ChakraDialog.CloseTriggerProps) => {
  // Props
  const { onClick, ...restProps } = props;

  // Contexts
  const { close, setFullscreen } = useDialogContext();

  return (
    <ChakraDialog.CloseTrigger
      asChild
      pos={"absolute"}
      top={3.5}
      right={3.5}
      {...restProps}
      onClick={(event) => {
        if (close) {
          close();
        } else {
          back();
        }
        setTimeout(() => setFullscreen(false), 200);
        onClick?.(event);
      }}
    />
  );
};

const DialogCloseButton = (props: DialogCloseButtonProps) => {
  // Props
  const { closeTriggerProps, ...restProps } = props;

  return (
    <DialogCloseTrigger {...closeTriggerProps}>
