const DialogFullscreenButton = (props: IconButtonProps) => {
  // Contexts
  const { modalKey, fullscreen, setFullscreen } = useDialogContext();

  return (
    <IconButton
      size={"2xs"}
      variant={"subtle"}
      bg={"an1"}
      rounded={"full"}
      pos={"absolute"}
      top={3.5}
