// src/design-system/components/toast/hooks/use-toast-history.ts

import { useMemo } from "react";
import { useToastHistoryStore } from "@/design-system/components/toast/stores/toast-history.store";
import type { HistoryEntry } from "@/design-system/components/toast/types/toast.type";

export type HistoryGroupStack = {
  group: string;
  entries: HistoryEntry[];
};

export function useToastHistory() {
  // Subscribing to `entries` keeps this reactive; `getAll()` (not the raw
  // field) is applied below to respect TTL + soft-delete filtering.
  useToastHistoryStore((state) => state.entries);
  const all = useToastHistoryStore.getState().getAll();

  const groups: HistoryGroupStack[] = useMemo(() => {
    const byGroup = new Map<string, HistoryEntry[]>();
    for (const entry of all) {
      const list = byGroup.get(entry.group) ?? [];
      list.push(entry);
      byGroup.set(entry.group, list);
    }
    return Array.from(byGroup.entries()).map(([group, entries]) => ({
      group,
      entries: entries.sort((a, b) => b.createdAt - a.createdAt),
    }));
  }, [all]);

  const { deleteOne, deleteMany, clear, markRead, markAllRead } =
    useToastHistoryStore.getState();

  return { groups, all, deleteOne, deleteMany, clear, markRead, markAllRead };
}

// src/design-system/components/toast/hooks/use-visible-toasts.ts

// [ARCHIVED] – previously used for grouped toast rendering (per-group stacks).
// Kept as reference if grouped view is ever reintroduced.

import { useToastVisibleStore } from "@/design-system/components/toast/stores/toast-visible.store";
import { getToastConfig } from "@/design-system/components/toast/core/toast.config";
import type { ToastItemData } from "@/design-system/components/toast/types/toast.type";

export type ToastGroupStack = {
  group: string;
  items: ToastItemData[];
};

function orderRecords(
  records: ToastItemData[],
  newestOnTop: boolean,
): ToastItemData[] {
  const sorted = [...records].sort((a, b) => a.createdAt - b.createdAt);
  return newestOnTop ? sorted.reverse() : sorted;
}

/** Returns every group as a ready-to-render stack. */
export function useVisibleToastGroups(): ToastGroupStack[] {
  const entries = useToastVisibleStore((state) => state.entries);
  const { newestOnTop } = getToastConfig();

  return Object.entries(entries).map(([group, records]) => ({
    group,
    items: orderRecords(records, newestOnTop),
  }));
}

/** Single-group variant, useful when a consumer only renders one known group. */
export function useVisibleToastGroup(group: string): ToastGroupStack {
  const records = useToastVisibleStore((state) => state.entries[group] ?? []);
  const { newestOnTop } = getToastConfig();
  return { group, items: orderRecords(records, newestOnTop) };
}

