    if (!reason.trim()) return;
    rejectMutation.mutate(
      {
        orderId: order.orderId,
        reason: reason.trim(),
      },
      {
        onSuccess: () => {
          if (isOpen) back();
          onSuccessRedirect?.();
        },
      },
    );
  };

  return (
    <Modal.Content>
      <Modal.Header>
        <Modal.CloseButton />

        <VStack gap={"xs"}>
          <Modal.Title>{"Tolak Permohonan Pesanan"}</Modal.Title>

