      <Modal.Footer>
        <VStack gap={"xs"} w={"full"}>
          <Button
            variant={"solid"}
            colorPalette={"red"}
            disabled={!reason.trim() || rejectMutation.isPending}
            loading={rejectMutation.isPending}
            onClick={handleReject}
          >
            <AppIcon icon={XCircleIcon} />
            {"Tolak Pesanan"}
          </Button>

          <Button onClick={back}>{"Batal"}</Button>
        </VStack>
      </Modal.Footer>
    </Modal.Content>
  );
};

