                  const totalKawasanHa = order.items
                    .filter((i) => i.spatialBasis === "kawasan")
                    .reduce((sum, item) => sum + (item.areaHa ?? 0), 0);

                  const layerTitles = order.items
                    .map((i) => i.sourceLayerTitle)
