                          <HStack justify={"space-between"} align={"center"}>
                            <P color={"fg.muted"}>{"Volume Spasial:"}</P>
                            <P fontWeight={"medium"}>
                              {totalBidang > 0 && (
                                <>
                                  <TNum>{totalBidang}</TNum> {"bidang"}
                                </>
                              )}
                              {totalBidang > 0 && totalKawasanHa > 0 && " • "}
                              {totalKawasanHa > 0 && (
                                <>
                                  <TNum>{totalKawasanHa}</TNum> {"ha"}
                                </>
                              )}
