                          </HStack>

                          <HStack justify={"space-between"} align={"center"}>
                            <P color={"fg.muted"}>{"Total Estimasi:"}</P>
                            <P fontWeight={"semibold"} color={"blue.fg"}>
                              <FormatNumber
                                value={order.totalPrice}
                                style={"currency"}
