import { useThemeStore } from "@/design-system/stores/theme-store";
import {
  useRejectHelpCenterTicket,
  useResolveHelpCenterTicket,
} from "@/features/mitra/help-center/hooks/use-help-center.query";
import type React from "react";
import { useState } from "react";

export type HelpCenterModalResolveRejectTriggerProps = {
  ticketId: number | string;
  actionType: "resolve" | "reject";
  children: React.ReactNode;
};

export const HelpCenterModalResolveRejectTrigger = (
  props: HelpCenterModalResolveRejectTriggerProps,
) => {
  // Props
  const { ticketId, actionType, children } = props;

  // Stores
  const { theme } = useThemeStore();
  const isResolve = actionType === "resolve";
  const modalKey = `${actionType}HelpCenterModal-${ticketId}`;

  const { isOpen, open, close } = usePopModal({
    modalKey,
  });

  const resolveMutation = useResolveHelpCenterTicket(ticketId);
  const rejectMutation = useRejectHelpCenterTicket(ticketId);
  const isPending = isResolve
    ? resolveMutation.isPending
    : rejectMutation.isPending;

  // States
  const [message, setMessage] = useState<string>("");

  // Handlers
  const handleClose = () => {
    setMessage("");
    close();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!message.trim()) return;

    if (isResolve) {
      await resolveMutation.mutateAsync({
        reason: message.trim(),
      });
    } else {
      await rejectMutation.mutateAsync({
        reason: message.trim(),
      });
    }

    handleClose();
  };

  return (
    <Modal.Root
      modalKey={modalKey}
      opened={isOpen}
      open={open}
      close={handleClose}
      size={"md"}
    >
      <Modal.Trigger>{children}</Modal.Trigger>

      <Modal.Content>
        <Modal.Header>
          <Modal.Title w={"full"} fontWeight={"semibold"}>
            {isResolve ? "Selesaikan Laporan" : "Tolak Laporan"}
          </Modal.Title>

          <Modal.CloseButton />
        </Modal.Header>

        <Modal.Body>
          <form id={`form-${modalKey}`} onSubmit={handleSubmit}>
            <VStack gap={"md"} align={"stretch"}>
              <P fontSize={"sm"} color={"fg.muted"}>
                {isResolve
                  ? "Berikan catatan atau penjelasan mengenai penyelesaian kendala ini sebelum menandainya sebagai selesai."
                  : "Berikan alasan penolakan laporan kendala ini agar pelapor memahami keputusannya."}
              </P>

              <Field
                label={isResolve ? "Catatan Penyelesaian" : "Alasan Penolakan"}
              >
                <Textarea
                  placeholder={
                    isResolve
                      ? ": Kendala data telah berhasil diperbaiki dan diverifikasi..."
                      : ": Laporan tidak memenuhi kriteria / data tidak lengkap..."
                  }
                  rows={4}
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                />
              </Field>
            </VStack>
          </form>
        </Modal.Body>

        <Modal.Footer>
          <Button flex={1} variant={"outline"} onClick={handleClose}>
            {"Batal"}
          </Button>

          <Button
            flex={1}
            type={"submit"}
            form={`form-${modalKey}`}
            colorPalette={isResolve ? `${theme.colorPalette}` : "red"}
            loading={isPending}
            disabled={!message.trim()}
            variant={isResolve ? "solid" : "outline"}
          >
            {isResolve ? "Selesaikan" : "Tolak Laporan"}
          </Button>
        </Modal.Footer>
      </Modal.Content>
    </Modal.Root>
  );
};

