// src/shared/hooks/use-paginated-query.ts

import type {
  PaginatedParams,
  PaginatedResponse,
} from "@/shared/types/common-response.type";
import {
  keepPreviousData,
  type QueryKey,
  type UseQueryOptions,
  useQuery,
} from "@tanstack/react-query";
import { useState } from "react";

export type UsePaginatedQueryOptions<
  TItem,
  TParams extends PaginatedParams = PaginatedParams,
> = {
  queryKey: (params: TParams & { page: number; pageSize: number }) => QueryKey;
  fetcher: (
    params: TParams & { page: number; pageSize: number; signal?: AbortSignal },
  ) => Promise<PaginatedResponse<TItem>>;
  params?: TParams;
  initialPage?: number;
  initialPageSize?: number;
  staleTime?: number;
  enabled?: boolean;
  queryOptions?: Omit<
    UseQueryOptions<PaginatedResponse<TItem>, Error>,
    "queryKey" | "queryFn"
  >;
};

export const usePaginatedQuery = <
  TItem,
  TParams extends PaginatedParams = PaginatedParams,
>(
  options: UsePaginatedQueryOptions<TItem, TParams>,
) => {
  // Config & States
  const {
    queryKey,
    fetcher,
    params,
    initialPage = 1,
    initialPageSize = 10,
    staleTime = 60 * 1000,
    enabled = true,
    queryOptions,
  } = options;

  // States
  const [page, setPage] = useState(initialPage);
  const [pageSize, setPageSize] = useState(initialPageSize);

  // Combined Params
  const queryParams = {
    ...(params as TParams),
    page,
    pageSize,
  };

  // Query
  const query = useQuery({
    queryKey: queryKey(queryParams),
    queryFn: ({ signal }) => fetcher({ ...queryParams, signal }),
    placeholderData: keepPreviousData,
    staleTime,
    enabled,
    ...queryOptions,
  });

  // Derived Values
  const items = query.data?.items ?? [];
  const total = query.data?.pagination?.totalItems ?? 0;
  const totalPages = query.data?.pagination?.totalPages ?? 1;

  return {
    ...query,
    items,
    total,
    totalPages,
    page,
    pageSize,
    setPage,
    setPageSize,
  };
};

import { router } from "@/app/router";
import { toast } from "@/design-system/components/toast";
import { ApiError } from "@/shared/libs/api-client/api-error";

export type RequestOptions = Omit<RequestInit, "body"> & {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  body?: any;
  params?: Record<string, string | number | boolean | undefined>;
  toastId?: string;
};

const getAuthToken = (): string | null => {
  if (typeof window === "undefined") return null;
  return localStorage.getItem("auth_token");
};

export const apiClient = {
  request: async <T>(
    endpoint: string,
    options: RequestOptions = {},
  ): Promise<T> => {
    const { body, params, headers: customHeaders, ...restOptions } = options;

    const baseUrl = import.meta.env.VITE_API_BASE_URL || "";
    let url =
      endpoint.startsWith("http://") || endpoint.startsWith("https://")
        ? endpoint
        : `${baseUrl}${endpoint.startsWith("/") ? "" : "/"}${endpoint}`;
    if (params) {
      const searchParams = new URLSearchParams();
      Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
          searchParams.append(key, String(value));
        }
      });
      const queryString = searchParams.toString();
      if (queryString) {
        url += (url.includes("?") ? "&" : "?") + queryString;
      }
    }

    const token = getAuthToken();

    const headers: Record<string, string> = {
      Accept: "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(customHeaders as Record<string, string>),
    };

    let serializedBody: BodyInit | null = null;
    if (body) {
      if (body instanceof FormData || body instanceof URLSearchParams) {
        serializedBody = body;
      } else {
        headers["Content-Type"] = "application/json";
        serializedBody = JSON.stringify(body);
      }
    }

    try {
      const response = await fetch(url, {
        ...restOptions,
        headers,
        body: serializedBody,
      });

      if (!response.ok) {
        let errorMessage = `HTTP Error ${response.status}: ${response.statusText}`;
        let errorData: Record<string, string[]> | undefined = undefined;

        try {
          const jsonError = await response.json();
          if (jsonError.message) errorMessage = jsonError.message;
          if (jsonError.errors) errorData = jsonError.errors;
        } catch {
          // Fallback if response is not JSON
        }

        const isAuthEndpoint =
          endpoint.includes("/auth/me") || endpoint.includes("/auth/verify");

        if (response.status === 401 || (response.status === 403 && isAuthEndpoint)) {
          if (typeof window !== "undefined") {
            localStorage.removeItem("auth_token");
            localStorage.removeItem("user");
            sessionStorage.removeItem("user");

            // If we are on private pages or not already on login root, navigate to root
            const isPublicPage =
              window.location.pathname === "/" ||
              window.location.pathname === "/admin";
            if (!isPublicPage) {
              toast.error(
                response.status === 401
                  ? "Sesi Anda telah berakhir"
                  : "Akses Akun Ditolak",
                {
                  id: "auth-session-expired-toast",
                  group: "Sistem",
                  description:
                    errorMessage ||
                    "Akun Anda tidak memiliki akses atau telah dinonaktifkan.",
                },
              );

              void router.navigate({ to: "/" });
            }
          }
        }

        throw new ApiError(errorMessage, response.status, errorData);
      }

      // Handle 204 No Content
      if (response.status === 204) {
        return {} as T;
      }

      return (await response.json()) as T;
    } catch (err: unknown) {
      if (err instanceof ApiError) {
        throw err;
      }
      if ((err as { name?: string }).name === "AbortError") {
        throw err;
      }
      throw new ApiError(
        err instanceof Error ? err.message : "Terjadi kesalahan jaringan",
        0,
      );
    }
  },

  get: <T>(endpoint: string, options?: RequestOptions): Promise<T> =>
    apiClient.request<T>(endpoint, { ...options, method: "GET" }),

  post: <T>(
    endpoint: string,
    body?: unknown,
    options?: RequestOptions,
  ): Promise<T> =>
    apiClient.request<T>(endpoint, { ...options, method: "POST", body }),

  put: <T>(
    endpoint: string,
    body?: unknown,
    options?: RequestOptions,
  ): Promise<T> =>
    apiClient.request<T>(endpoint, { ...options, method: "PUT", body }),

  patch: <T>(
    endpoint: string,
    body?: unknown,
    options?: RequestOptions,
  ): Promise<T> =>
    apiClient.request<T>(endpoint, { ...options, method: "PATCH", body }),

  delete: <T>(endpoint: string, options?: RequestOptions): Promise<T> =>
    apiClient.request<T>(endpoint, { ...options, method: "DELETE" }),
};

// src/shared/libs/i18n/locale-provider.tsx

import {
  createContext,
  useContext,
  useState,
  useCallback,
  type ReactNode,
} from "react";
import {
  setLocale as paraglideSetLocale,
  getLocale,
  type Locale,
} from "@/paraglide/runtime";

export type LocaleContextValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
};

const LocaleContext = createContext<LocaleContextValue | null>(null);

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(getLocale());

  const setLocale = useCallback((newLocale: Locale) => {
    paraglideSetLocale(newLocale, { reload: false });
    setLocaleState(newLocale);
  }, []);

  return (
    <LocaleContext.Provider value={{ locale, setLocale }}>
      <div id={"locale-provider"} key={locale}>
        {children}
      </div>
    </LocaleContext.Provider>
  );
}

export function useLocale() {
  const ctx = useContext(LocaleContext);
  if (!ctx) throw new Error("useLocale must be used within LocaleProvider");
  return ctx;
}

// src/shared/libs/toast/toast.handler.ts

import { toast } from "@/design-system/components/toast";

export type ToastMessageConfig = {
  title: string;
  description?: string;
};

export type MutationToastOptions = {
  group?: string;
  loadingMessage?: ToastMessageConfig;
  successMessage?: ToastMessageConfig;
  errorMessage?: ToastMessageConfig;
};

/**
 * Mutation Toast Handler Helper
 *
 * Connects TanStack Query mutation lifecycle (onMutate, onSuccess, onError)
 * directly to the application's Toast Engine with categorized groups.
 */
export const mutationToastHandlers = (
  key: string,
  options: MutationToastOptions = {},
) => {
  const toastId = `mutation-toast-${key}`;
  const group = options.group;

  return {
    onLoading: () => {
      if (options.loadingMessage) {
        toast.loading(options.loadingMessage.title, {
          id: toastId,
          group,
          description: options.loadingMessage.description,
        });
      }
    },
    onSuccess: () => {
      if (options.successMessage) {
        toast.success(options.successMessage.title, {
          id: toastId,
          group,
          description: options.successMessage.description,
        });
      } else {
        toast.close(toastId);
      }
    },
    onError: (error: unknown) => {
      let errorMessageString = "Terjadi kesalahan";
      if (error instanceof Error) {
        errorMessageString = error.message;
      }

      const title = options.errorMessage?.title ?? errorMessageString;
      const description =
        options.errorMessage?.description ??
        (options.errorMessage?.title &&
        errorMessageString !== options.errorMessage.title
          ? errorMessageString
          : undefined);

      toast.error(title, {
        id: toastId,
        group,
        description,
      });
    },
  };
};

// src/shared/utils/formatter/byte.formatter.ts

export type ByteUnit =
  | "B"
  | "KB"
  | "MB"
  | "GB"
  | "TB"
  | "PB"
  | "EB"
  | "ZB"
  | "YB";

export interface FormatByteOptions {
  unit?: ByteUnit;
  decimals?: number;
}

const UNITS: ByteUnit[] = ["B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"];

/**
 * Formats a byte number to a human-readable string, with optional forced unit.
 *
 * @param value The byte value to format
 * @param options Options to force unit and control decimals
 * @returns Formatted byte string, or empty string if value is null/undefined
 */
export function formatByte(
  value: number | null | undefined,
  options: FormatByteOptions = {},
): string {
  if (value === null || value === undefined) {
    return "";
  }

  const { unit, decimals = 0 } = options;

  if (value === 0) {
    const targetUnit = unit || "B";
    return `0 ${targetUnit}`;
  }

  const k = 1024;

  if (unit) {
    const i = UNITS.indexOf(unit);
    if (i !== -1) {
      const formattedValue = (value / Math.pow(k, i)).toFixed(decimals);
      const numValue = parseFloat(formattedValue);
      return `${numValue} ${unit}`;
    }
  }

  // Automatic format
  const i = Math.min(
    Math.floor(Math.log(Math.abs(value)) / Math.log(k)),
    UNITS.length - 1,
  );
  const targetUnit = UNITS[i];
  const formattedValue = (value / Math.pow(k, i)).toFixed(decimals);
  const numValue = parseFloat(formattedValue);
  return `${numValue} ${targetUnit}`;
}

import { getLocale } from "@/paraglide/runtime";

export type FormatNumberStyle = "decimal" | "currency" | "percent" | "unit";
export type FormatNumberNotation =
  | "standard"
  | "scientific"
  | "engineering"
  | "compact";
export type FormatNumberCompactDisplay = "short" | "long";
export type FormatNumberCurrencyDisplay =
  | "symbol"
  | "narrowSymbol"
  | "code"
  | "name";
export type FormatNumberUnitDisplay = "short" | "long" | "narrow";
export type FormatNumberSignDisplay =
  | "auto"
  | "never"
  | "always"
  | "exceptZero";

export type FormatNumberOptions = {
  locale?: string;
  style?: FormatNumberStyle;
  currency?: string;
  currencyDisplay?: FormatNumberCurrencyDisplay;
  unit?: string;
  unitDisplay?: FormatNumberUnitDisplay;
  notation?: FormatNumberNotation;
  compactDisplay?: FormatNumberCompactDisplay;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  minimumIntegerDigits?: number;
  minimumSignificantDigits?: number;
  maximumSignificantDigits?: number;
  signDisplay?: FormatNumberSignDisplay;
  useGrouping?: boolean;
};

function getActiveLocale(locale?: string): string {
  if (locale) return locale;
  try {
    const current = getLocale();
    return current === "en" ? "en-US" : "id-ID";
  } catch {
    return "id-ID";
  }
}

/**
 * Format a number using Intl.NumberFormat with dynamic active locale.
 * Supports decimal, currency (IDR), percent, unit, compact, and scientific notations.
 */
export function formatNumber(
  value: number,
  options: FormatNumberOptions = {},
): string {
  const {
    locale,
    style = "decimal",
    currency = "IDR",
    currencyDisplay = "symbol",
    unit,
    unitDisplay = "short",
    notation = "standard",
    compactDisplay = "short",
    minimumFractionDigits,
    maximumFractionDigits,
    minimumIntegerDigits,
    minimumSignificantDigits,
    maximumSignificantDigits,
    signDisplay = "auto",
    useGrouping = true,
  } = options;

  const intlOptions: Intl.NumberFormatOptions = {
    style,
    notation,
    compactDisplay,
    signDisplay,
    useGrouping,
  };

  if (style === "currency") {
    intlOptions.currency = currency;
    intlOptions.currencyDisplay = currencyDisplay;
  }

  if (style === "unit" && unit) {
    intlOptions.unit = unit;
    intlOptions.unitDisplay = unitDisplay;
  }

  if (minimumFractionDigits !== undefined)
    intlOptions.minimumFractionDigits = minimumFractionDigits;
  if (maximumFractionDigits !== undefined)
    intlOptions.maximumFractionDigits = maximumFractionDigits;
  if (minimumIntegerDigits !== undefined)
    intlOptions.minimumIntegerDigits = minimumIntegerDigits;
  if (minimumSignificantDigits !== undefined)
    intlOptions.minimumSignificantDigits = minimumSignificantDigits;
  if (maximumSignificantDigits !== undefined)
    intlOptions.maximumSignificantDigits = maximumSignificantDigits;

  return new Intl.NumberFormat(getActiveLocale(locale), intlOptions).format(
    value,
  );
}

// ---------------------------------------------------------------------------
// Shorthand helpers

/** 1500000 → "1.500.000" (id) / "1,500,000" (en) */
export function formatDecimal(value: number, locale?: string): string {
  return formatNumber(value, { locale });
}

/** 1500000 → "Rp1.500.000" (id) / "IDR 1,500,000" (en) */
export function formatCurrency(
  value: number,
  currency = "IDR",
  locale?: string,
): string {
  return formatNumber(value, {
    locale,
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  });
}

/** 0.75 → "75%" */
export function formatPercent(
  value: number,
  maximumFractionDigits = 1,
  locale?: string,
): string {
  return formatNumber(value, {
    locale,
    style: "percent",
    maximumFractionDigits,
  });
}

/** 1500000 → "1,5 jt" (id) / "1.5M" (en) */
export function formatCompact(
  value: number,
  compactDisplay: FormatNumberCompactDisplay = "short",
  locale?: string,
): string {
  return formatNumber(value, { locale, notation: "compact", compactDisplay });
}

/** 15000000 → "Rp 15 jt" (id) / "IDR 15M" (en) */
export function formatCompactCurrency(
  value: number,
  currency = "IDR",
  compactDisplay: FormatNumberCompactDisplay = "short",
  locale?: string,
): string {
  return formatNumber(value, {
    locale,
    style: "currency",
    currency,
    notation: "compact",
    compactDisplay,
    maximumFractionDigits: 1,
  });
}

/** 1500 → "1,5rb" or "1,5 ribu" */
export function formatCompactLong(value: number, locale?: string): string {
  return formatCompact(value, "long", locale);
}

/** 75 → "+75" / "-75" */
export function formatSigned(value: number, locale?: string): string {
  return formatNumber(value, { locale, signDisplay: "always" });
}

/** 1234.5678 → "1,23E3" */
export function formatScientific(value: number, locale?: string): string {
  return formatNumber(value, { locale, notation: "scientific" });
}

// src/shared/utils/navigation/recent-nav.utils.ts

import { getStorage, setStorage } from "@/shared/utils/client/client.storage";

const RECENT_NAVS_STORAGE_KEY = "volatil_recent_navs";
const MAX_RECENT_NAVS = 3;

export type RecentNavItem = {
  pathname: string;
  titleKey: string;
  visitedAt: number;
};

export const getRecentNavs = (): RecentNavItem[] => {
  const raw = getStorage(RECENT_NAVS_STORAGE_KEY);
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) {
      return parsed;
    }
    return [];
  } catch {
    return [];
  }
};

export const recordRecentNav = (item: {
  pathname: string;
  titleKey: string;
}): void => {
  if (!item.pathname || item.pathname.includes("/welcome")) return;

  const current = getRecentNavs();
  const filtered = current.filter((nav) => nav.pathname !== item.pathname);
  const updated: RecentNavItem[] = [
    {
      pathname: item.pathname,
      titleKey: item.titleKey,
      visitedAt: Date.now(),
    },
    ...filtered,
  ].slice(0, MAX_RECENT_NAVS);

  setStorage(RECENT_NAVS_STORAGE_KEY, JSON.stringify(updated));
};
